package audit

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/hashicorp/go-multierror"
	"go.opentelemetry.io/otel/attribute"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"
)

const (
	eventVersion          = "0.1"
	eventVersionKey       = "flipt.event.version"
	eventActionKey        = "flipt.event.action"
	eventTypeKey          = "flipt.event.type"
	eventMetadataActorKey = "flipt.event.metadata.actor"
	eventPayloadKey       = "flipt.event.payload"
	eventTimestampKey     = "flipt.event.timestamp"
)

// Type represents what resource is being acted on.
type Type string

// Action represents the action being taken on the resource.
type Action string

const (
	ConstraintType   Type = "constraint"
	DistributionType Type = "distribution"
	FlagType         Type = "flag"
	NamespaceType    Type = "namespace"
	RolloutType      Type = "rollout"
	RuleType         Type = "rule"
	SegmentType      Type = "segment"
	TokenType        Type = "token"
	VariantType      Type = "variant"

	Create Action = "created"
	Delete Action = "deleted"
	Update Action = "updated"
)

// Event holds information that represents an audit internally.
type Event struct {
	Version string `json:"version"`
	Type    Type   `json:"type"`
	Action  Action `json:"action"`

	Metadata Metadata `json:"metadata"`

	Payload interface{} `json:"payload"`

	Timestamp string `json:"timestamp"`
}

// GRPCMethodToAction returns the Action from the gRPC method.
func GRPCMethodToAction(method string) Action {
	if strings.Contains(method, "Create") {
		return Create
	} else if strings.Contains(method, "Update") {
		return Update
	}

	return ""
}

// DecodeToAttributes provides a helper method for an Event that will return
// a value compatible to a SpanEvent.
func (e Event) DecodeToAttributes() []attribute.KeyValue {
	akv := make([]attribute.KeyValue, 0)

	if e.Version != "" {
		akv = append(akv, attribute.KeyValue{
			Key:   eventVersionKey,
			Value: attribute.StringValue(e.Version),
		})
	}

	if e.Action != "" {
		akv = append(akv, attribute.KeyValue{
			Key:   eventActionKey,
			Value: attribute.StringValue(string(e.Action)),
		})
	}

	if e.Type != "" {
		akv = append(akv, attribute.KeyValue{
			Key:   eventTypeKey,
			Value: attribute.StringValue(string(e.Type)),
		})
	}

	if e.Timestamp != "" {
		akv = append(akv, attribute.KeyValue{
			Key:   eventTimestampKey,
			Value: attribute.StringValue(e.Timestamp),
		})
	}

	b, err := json.Marshal(e.Metadata.Actor)
	if err == nil {
		akv = append(akv, attribute.KeyValue{
			Key:   eventMetadataActorKey,
			Value: attribute.StringValue(string(b)),
		})
	}

	if e.Payload != nil {
		b, err := json.Marshal(e.Payload)
		if err == nil {
			akv = append(akv, attribute.KeyValue{
				Key:   eventPayloadKey,
				Value: attribute.StringValue(string(b)),
			})
		}
	}

	return akv
}

func (e *Event) AddToSpan(ctx context.Context) {
	span := trace.SpanFromContext(ctx)
	span.AddEvent("event", trace.WithAttributes(e.DecodeToAttributes()...))
}

func (e *Event) Valid() bool {
	return e.Version != "" && e.Action != "" && e.Type != "" && e.Timestamp != "" && e.Payload != nil
}

var errEventNotValid = errors.New("audit event not valid")

// decodeToEvent provides helper logic for turning to value of SpanEvents to
// an Event.
func decodeToEvent(kvs []attribute.KeyValue) (*Event, error) {
	e := new(Event)
	for _, kv := range kvs {
		switch string(kv.Key) {
		case eventVersionKey:
			e.Version = kv.Value.AsString()
		case eventActionKey:
			e.Action = Action(kv.Value.AsString())
		case eventTypeKey:
			e.Type = Type(kv.Value.AsString())
		case eventTimestampKey:
			e.Timestamp = kv.Value.AsString()
		case eventMetadataActorKey:
			var actor map[string]string
			if err := json.Unmarshal([]byte(kv.Value.AsString()), &actor); err != nil {
				return nil, err
			}
			e.Metadata.Actor = actor
		case eventPayloadKey:
			var payload interface{}
			if err := json.Unmarshal([]byte(kv.Value.AsString()), &payload); err != nil {
				return nil, err
			}
			e.Payload = payload
		}
	}

	if !e.Valid() {
		return nil, errEventNotValid
	}

	return e, nil
}

// Metadata holds information of what metadata an event will contain.
type Metadata struct {
	Actor map[string]string `json:"actor,omitempty"`
}

// Sink is the abstraction for various audit sink configurations
// that Flipt will support.
type Sink interface {
	SendAudits(context.Context, []Event) error
	Close() error
	fmt.Stringer
}

// SinkSpanExporter sends audit logs to configured sinks through intercepting span events.
type SinkSpanExporter struct {
	sinks  []Sink
	logger *zap.Logger
}

// EventExporter provides an API for exporting spans as Event(s).
type EventExporter interface {
	ExportSpans(ctx context.Context, spans []sdktrace.ReadOnlySpan) error
	Shutdown(ctx context.Context) error
	SendAudits(ctx context.Context, es []Event) error
}

// NewSinkSpanExporter is the constructor for a SinkSpanExporter.
func NewSinkSpanExporter(logger *zap.Logger, sinks []Sink) EventExporter {
	return &SinkSpanExporter{
		sinks:  sinks,
		logger: logger,
	}
}

// ExportSpans completes one part of the implementation of a SpanExporter. Decodes span events to audit events.
func (s *SinkSpanExporter) ExportSpans(ctx context.Context, spans []sdktrace.ReadOnlySpan) error {
	es := make([]Event, 0)

	for _, span := range spans {
		events := span.Events()
		for _, e := range events {
			e, err := decodeToEvent(e.Attributes)
			if err != nil {
				if !errors.Is(err, errEventNotValid) {
					s.logger.Error("audit event not decodable", zap.Error(err))
				}
				continue
			}
			es = append(es, *e)
		}
	}

	return s.SendAudits(ctx, es)
}

// Shutdown will close all the registered sinks.
func (s *SinkSpanExporter) Shutdown(ctx context.Context) error {
	var result error

	for _, sink := range s.sinks {
		err := sink.Close()
		if err != nil {
			result = multierror.Append(result, err)
		}
	}

package config

import (
	"errors"
	"time"

	"github.com/spf13/viper"
)

// cheers up the unparam linter
var _ defaulter = (*AuditConfig)(nil)

// AuditConfig contains fields, which enable and configure
// Flipt's various audit sink mechanisms.
type AuditConfig struct {
	Sinks  SinksConfig  `json:"sinks,omitempty" mapstructure:"sinks"`
	Buffer BufferConfig `json:"buffer,omitempty" mapstructure:"buffer"`
	Events []string     `json:"events,omitempty" mapstructure:"events"`
}

// Enabled returns true if any nested sink is enabled
func (c *AuditConfig) Enabled() bool {
	return c.Sinks.LogFile.Enabled || c.Sinks.Webhook.Enabled
}

func (c *AuditConfig) setDefaults(v *viper.Viper) error {
	v.SetDefault("audit", map[string]any{
		"sinks": map[string]any{
			"log": map[string]any{
				"enabled": "false",
				"file":    "",
			},
			"webhook": map[string]any{
				"enabled": "false",
			},
		},
		"buffer": map[string]any{
			"capacity":     2,
			"flush_period": "2m",
		},
		"events": []string{"*:*"},
	})

	return nil
}

func (c *AuditConfig) validate() error {
	if c.Sinks.LogFile.Enabled && c.Sinks.LogFile.File == "" {
		return errors.New("file not specified")
	}

	if c.Sinks.Webhook.Enabled && c.Sinks.Webhook.URL == "" {
		return errors.New("url not provided")
	}

	if c.Buffer.Capacity < 2 || c.Buffer.Capacity > 10 {
		return errors.New("buffer capacity below 2 or above 10")
	}

	if c.Buffer.FlushPeriod < 2*time.Minute || c.Buffer.FlushPeriod > 5*time.Minute {
		return errors.New("flush period below 2 minutes or greater than 5 minutes")
	}

	return nil
}

// SinksConfig contains configuration held in structures for the different sinks
// that we will send audits to.
type SinksConfig struct {
	LogFile LogFileSinkConfig `json:"log,omitempty" mapstructure:"log"`
	Webhook WebhookSinkConfig `json:"webhook,omitempty" mapstructure:"webhook"`
}

// WebhookSinkConfig contains configuration for sending POST requests to specific
// URL as its configured.
type WebhookSinkConfig struct {
	Enabled            bool          `json:"enabled,omitempty" mapstructure:"enabled"`
	URL                string        `json:"url,omitempty" mapstructure:"url"`
	MaxBackoffDuration time.Duration `json:"maxBackoffDuration,omitempty" mapstructure:"max_backoff_duration"`
	SigningSecret      string        `json:"signingSecret,omitempty" mapstructure:"signing_secret"`
}

// LogFileSinkConfig contains fields that hold configuration for sending audits
// to a log file.
type LogFileSinkConfig struct {
	Enabled bool   `json:"enabled,omitempty" mapstructure:"enabled"`
	File    string `json:"file,omitempty" mapstructure:"file"`
}

// BufferConfig holds configuration for the buffering of sending the audit
// events to the sinks.
type BufferConfig struct {
	Capacity    int           `json:"capacity,omitempty" mapstructure:"capacity"`
	FlushPeriod time.Duration `json:"flushPeriod,omitempty" mapstructure:"flush_period"`
}

package audit

import (
	"errors"
	"fmt"
	"strings"
)

// Checker holds a map that maps event pairs to a dummy struct. It is basically
// used as a set to check for existence.
type Checker struct {
	eventActions map[string]struct{}
}

// NewChecker is the constructor for a Checker.
func NewChecker(eventPairs []string) (*Checker, error) {
	nouns := map[string][]string{
		"constraint":   {"constraint"},
		"distribution": {"distribution"},
		"flag":         {"flag"},
		"namespace":    {"namespace"},
		"rollout":      {"rollout"},
		"rule":         {"rule"},
		"segment":      {"segment"},
		"variant":      {"variant"},
		"*":            {"constraint", "distribution", "flag", "namespace", "rollout", "rule", "segment", "variant"},
	}

	verbs := map[string][]string{
		"created": {"created"},
		"deleted": {"deleted"},
		"updated": {"updated"},
		"*":       {"created", "deleted", "updated"},
	}

	eventActions := make(map[string]struct{})
	for _, ep := range eventPairs {
		epSplit := strings.Split(ep, ":")
		if len(epSplit) < 2 {
			return nil, fmt.Errorf("invalid event pair: %s", ep)
		}

		eventNouns, ok := nouns[epSplit[0]]
		if !ok {
			return nil, fmt.Errorf("invalid noun: %s", epSplit[0])
		}

		eventVerbs, ok := verbs[epSplit[1]]
		if !ok {
			return nil, fmt.Errorf("invalid verb: %s", epSplit[1])
		}

		for _, en := range eventNouns {
			for _, ev := range eventVerbs {
				eventPair := fmt.Sprintf("%s:%s", en, ev)

				_, ok := eventActions[eventPair]
				if ok {
					return nil, fmt.Errorf("repeated event pair: %s", eventPair)
				}

				eventActions[eventPair] = struct{}{}
			}
		}
	}

	if len(eventActions) == 0 {
		return nil, errors.New("no event pairs exist")
	}

	return &Checker{
		eventActions: eventActions,
	}, nil
}

// Check checks if an event pair exists in the Checker data structure for event emission.
func (c *Checker) Check(eventPair string) bool {
	_, ok := c.eventActions[eventPair]
	return ok
}

// Events returns the type of events we would like to emit to configured sinks.
func (c *Checker) Events() []string {
	var events = make([]string, 0, len(c.eventActions))
	for k := range c.eventActions {
		events = append(events, k)
	}

	return events
}
package audit

import (
	"go.flipt.io/flipt/rpc/flipt"
)

// All types in this file represent an audit representation of the Flipt type that we will send to
// the different sinks.

type Flag struct {
	Key          string `json:"key"`
	Name         string `json:"name"`
	Description  string `json:"description"`
	Enabled      bool   `json:"enabled"`
	NamespaceKey string `json:"namespace_key"`
}

func NewFlag(f *flipt.Flag) *Flag {
	return &Flag{
		Key:          f.Key,
		Name:         f.Name,
		Description:  f.Description,
		Enabled:      f.Enabled,
		NamespaceKey: f.NamespaceKey,
	}
}

type Variant struct {
	Id           string `json:"id"`
	FlagKey      string `json:"flag_key"`
	Key          string `json:"key"`
	Name         string `json:"name"`
	Description  string `json:"description"`
	Attachment   string `json:"attachment"`
	NamespaceKey string `json:"namespace_key"`
}

func NewVariant(v *flipt.Variant) *Variant {
	return &Variant{
		Id:           v.Id,
		FlagKey:      v.FlagKey,
		Key:          v.Key,
		Name:         v.Name,
		Description:  v.Description,
		Attachment:   v.Attachment,
		NamespaceKey: v.NamespaceKey,
	}
}

type Constraint struct {
	Id           string `json:"id"`
	SegmentKey   string `json:"segment_key"`
	Type         string `json:"type"`
	Property     string `json:"property"`
	Operator     string `json:"operator"`
	Value        string `json:"value"`
	NamespaceKey string `json:"namespace_key"`
}

func NewConstraint(c *flipt.Constraint) *Constraint {
	return &Constraint{
		Id:           c.Id,
		SegmentKey:   c.SegmentKey,
		Type:         c.Type.String(),
		Property:     c.Property,
		Operator:     c.Operator,
		Value:        c.Value,
		NamespaceKey: c.NamespaceKey,
	}
}

type Namespace struct {
	Key         string `json:"key"`
	Name        string `json:"name"`
	Description string `json:"description"`
	Protected   bool   `json:"protected"`
}

func NewNamespace(n *flipt.Namespace) *Namespace {
	return &Namespace{
		Key:         n.Key,
		Name:        n.Name,
		Description: n.Description,
		Protected:   n.Protected,
	}
}

type Distribution struct {
	Id        string  `json:"id"`
	RuleId    string  `json:"rule_id"`
	VariantId string  `json:"variant_id"`
	Rollout   float32 `json:"rollout"`
}

func NewDistribution(d *flipt.Distribution) *Distribution {
	return &Distribution{
		Id:        d.Id,
		RuleId:    d.RuleId,
		VariantId: d.VariantId,
		Rollout:   d.Rollout,
	}
}

type Segment struct {
	Key          string        `json:"key"`
	Name         string        `json:"name"`
	Description  string        `json:"description"`
	Constraints  []*Constraint `json:"constraints"`
	MatchType    string        `json:"match_type"`
	NamespaceKey string        `json:"namespace_key"`
}

func NewSegment(s *flipt.Segment) *Segment {
	c := make([]*Constraint, 0, len(s.Constraints))
	for _, sc := range s.Constraints {
		c = append(c, NewConstraint(sc))
	}

	return &Segment{
		Key:          s.Key,
		Name:         s.Name,
		Description:  s.Description,
		Constraints:  c,
		MatchType:    s.MatchType.String(),
		NamespaceKey: s.NamespaceKey,
	}
}

type Rule struct {
	Id            string          `json:"id"`
	FlagKey       string          `json:"flag_key"`
	SegmentKey    string          `json:"segment_key"`
	Distributions []*Distribution `json:"distributions"`
	Rank          int32           `json:"rank"`
	NamespaceKey  string          `json:"namespace_key"`
}

func NewRule(r *flipt.Rule) *Rule {
	d := make([]*Distribution, 0, len(r.Distributions))
	for _, rd := range r.Distributions {
		d = append(d, NewDistribution(rd))
	}

	return &Rule{
		Id:            r.Id,
		FlagKey:       r.FlagKey,
		SegmentKey:    r.SegmentKey,
		Distributions: d,
		Rank:          r.Rank,
		NamespaceKey:  r.NamespaceKey,
	}
}

type Rollout struct {
	NamespaceKey string            `json:"namespace_key"`
	FlagKey      string            `json:"flag_key"`
	Rank         int32             `json:"rank"`
	Description  string            `json:"description"`
	Threshold    *RolloutThreshold `json:"threshold,omitempty"`
	Segment      *RolloutSegment   `json:"segment,omitempty"`
}

type RolloutThreshold struct {
	Percentage float32 `json:"percentage"`
	Value      bool    `json:"value"`
}

type RolloutSegment struct {
	Key   string `json:"key"`
	Value bool   `json:"value"`
}

func NewRollout(r *flipt.Rollout) *Rollout {
	rollout := &Rollout{
		NamespaceKey: r.NamespaceKey,
		FlagKey:      r.FlagKey,
		Rank:         r.Rank,
		Description:  r.Description,
	}

	switch rout := r.Rule.(type) {
	case *flipt.Rollout_Segment:
		rollout.Segment = &RolloutSegment{
			Key:   rout.Segment.SegmentKey,
			Value: rout.Segment.Value,
		}
	case *flipt.Rollout_Threshold:
		rollout.Threshold = &RolloutThreshold{
			Percentage: rout.Threshold.Percentage,
			Value:      rout.Threshold.Value,
		}
	}

	return rollout
}
package audit

import (
	"fmt"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestChecker(t *testing.T) {
	testCases := []struct {
		name          string
		eventPairs    []string
		expectedError error
		pairs         map[string]bool
	}{
		{
			name:          "wild card for nouns",
			eventPairs:    []string{"*:created"},
			expectedError: nil,
			pairs: map[string]bool{
				"constraint:created":   true,
				"distribution:created": true,
				"flag:created":         true,
				"namespace:created":    true,
				"rollout:created":      true,
				"rule:created":         true,
				"segment:created":      true,
				"variant:created":      true,
				"constraint:deleted":   false,
				"distribution:deleted": false,
				"flag:deleted":         false,
				"namespace:deleted":    false,
				"rollout:deleted":      false,
				"rule:deleted":         false,
				"segment:deleted":      false,
				"variant:deleted":      false,
				"constraint:updated":   false,
				"distribution:updated": false,
				"flag:updated":         false,
				"namespace:updated":    false,
				"rollout:updated":      false,
				"rule:updated":         false,
				"segment:updated":      false,
				"variant:updated":      false,
			},
		},
		{
			name:          "wild card for verbs",
			eventPairs:    []string{"flag:*"},
			expectedError: nil,
			pairs: map[string]bool{
				"constraint:created":   false,
				"distribution:created": false,
				"flag:created":         true,
				"namespace:created":    false,
				"rollout:created":      false,
				"rule:created":         false,
				"segment:created":      false,
				"variant:created":      false,
				"constraint:deleted":   false,
				"distribution:deleted": false,
				"flag:deleted":         true,
				"namespace:deleted":    false,
				"rollout:deleted":      false,
				"rule:deleted":         false,
				"segment:deleted":      false,
				"variant:deleted":      false,
				"constraint:updated":   false,
				"distribution:updated": false,
				"flag:updated":         true,
				"namespace:updated":    false,
				"rollout:updated":      false,
				"rule:updated":         false,
				"segment:updated":      false,
				"variant:updated":      false,
			},
		},
		{
			name:          "single pair",
			eventPairs:    []string{"flag:created"},
			expectedError: nil,
			pairs: map[string]bool{
				"constraint:created":   false,
				"distribution:created": false,
				"flag:created":         true,
				"namespace:created":    false,
				"rollout:created":      false,
				"rule:created":         false,
				"segment:created":      false,
				"variant:created":      false,
				"constraint:deleted":   false,
				"distribution:deleted": false,
				"flag:deleted":         false,
				"namespace:deleted":    false,
				"rollout:deleted":      false,
				"rule:deleted":         false,
				"segment:deleted":      false,
				"variant:deleted":      false,
				"constraint:updated":   false,
				"distribution:updated": false,
				"flag:updated":         false,
				"namespace:updated":    false,
				"rollout:updated":      false,
				"rule:updated":         false,
				"segment:updated":      false,
				"variant:updated":      false,
			},
		},
		{
			name:          "error repeating event pairs",
			eventPairs:    []string{"*:created", "flag:created"},
			expectedError: fmt.Errorf("repeated event pair: %s", "flag:created"),
		},
	}

	for _, tc := range testCases {
		checker, err := NewChecker(tc.eventPairs)
		if tc.expectedError != nil {
			assert.EqualError(t, err, tc.expectedError.Error())
			continue
		}

		for k, v := range tc.pairs {
			actual := checker.Check(k)
			assert.Equal(t, v, actual)
		}
	}
}
package audit

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"go.flipt.io/flipt/rpc/flipt"
)

func TestFlag(t *testing.T) {
	f := &flipt.Flag{
		Key:          "flipt",
		Name:         "flipt",
		NamespaceKey: "flipt",
		Enabled:      false,
	}
	nf := NewFlag(f)

	assert.Equal(t, nf.Enabled, f.Enabled)
	assert.Equal(t, nf.Key, f.Key)
	assert.Equal(t, nf.Name, f.Name)
	assert.Equal(t, nf.NamespaceKey, f.NamespaceKey)
}

func TestVariant(t *testing.T) {
	v := &flipt.Variant{
		Id:      "this-is-an-id",
		FlagKey: "flipt",
		Key:     "flipt",
		Name:    "flipt",
	}

	nv := NewVariant(v)
	assert.Equal(t, nv.Id, v.Id)
	assert.Equal(t, nv.FlagKey, v.FlagKey)
	assert.Equal(t, nv.Key, v.Key)
	assert.Equal(t, nv.Name, v.Name)
}

func testConstraintHelper(t *testing.T, c *flipt.Constraint) {
	t.Helper()
	nc := NewConstraint(c)
	assert.Equal(t, nc.Id, c.Id)
	assert.Equal(t, nc.SegmentKey, c.SegmentKey)
	assert.Equal(t, nc.Type, c.Type.String())
	assert.Equal(t, nc.Property, c.Property)
	assert.Equal(t, nc.Operator, c.Operator)
	assert.Equal(t, nc.Value, c.Value)
}
func TestConstraint(t *testing.T) {
	c := &flipt.Constraint{
		Id:         "this-is-an-id",
		SegmentKey: "flipt",
		Type:       flipt.ComparisonType_STRING_COMPARISON_TYPE,
		Property:   "string",
		Operator:   "eq",
		Value:      "flipt",
	}

	testConstraintHelper(t, c)
}
func TestNamespace(t *testing.T) {
